// Close on an API key: every operation of Close's API (its official OpenAPI spec), plus file upload and download.
// actions.json is generated by `bun scripts/openapi-actions.ts close`; leads, contacts, opportunities, tasks, every
// activity and the rest start automations by webhook (triggers.ts).
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { type Api, call, type Send, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const BASE = "https://api.close.com/api/v1";
const basic = (key: string) => `Basic ${Buffer.from(`${key}:`).toString("base64")}`;
export const api: Api = {
  name: "Close",
  base: BASE,
  tokenHelp: "Close → Settings → Developer → API Keys",
  // the key is the basic-auth username, with no password
  auth: (key) => ({ Authorization: basic(key) }),
  deadToken: (status, body) => status === 401 || body?.error_code === "inactive_api_key",
};

const ACTIONS = new URL("./actions.json", import.meta.url);
const generated = await specActions(ACTIONS, api);
// custom field values come in as {custom: {cf_...: value}} and go to Close as top-level "custom.cf_..." keys
const { actions: specs } = (await Bun.file(ACTIONS).json()) as { actions: { name: string; input: { properties: Record<string, unknown> }; send: Send }[] };
for (const a of specs) {
  if (!a.input.properties.custom || a.send.body?.kind !== "fields") continue;
  const fields = a.send.body.fields;
  generated[a.name]!.run = (i: Record<string, any>, key: string) => {
    const { custom, ...rest } = i;
    const extra = Object.keys(custom ?? {}).map((k) => `custom.${k.replace(/^custom\./, "")}`);
    const flat = Object.fromEntries(Object.entries(custom ?? {}).map(([k, v]) => [`custom.${k.replace(/^custom\./, "")}`, v]));
    return call(api, key, { ...a.send, body: { kind: "fields", fields: [...fields, ...extra.map((k): [string, string] => [k, k])] } }, { ...rest, ...flat });
  };
}

// Close's own hosts: only these get the key
const CLOSE_HOST = /^https:\/\/([a-z0-9-]+\.)*close\.(com|io)\//i;
const extras: Record<string, OwnAction> = {
  upload_file: {
    description:
      "Upload a file from the computer to Close. Answers its url, good for 24 hours: pass it with the filename to attach_file_to_lead, or in an email, note or opportunity's attachments.",
    input: z.object({ file: z.any().describe('The file: {"file": "/work/..."}') }),
    run: async (i: { file: unknown }, key: string) => {
      const file = i.file;
      if (!(file instanceof AppFile)) throw new AppsError('file: give the file as {"file": "/work/..."}');
      const got = (await call(api, key, { method: "POST", path: "/files/upload/", query: [], headers: [], body: { kind: "fields", fields: [["filename", "filename"], ["content_type", "content_type"]] } }, { filename: file.name, content_type: file.mimetype })) as {
        upload: { url: string; fields: Record<string, string> };
        download: { url: string };
      };
      const form = new FormData();
      for (const [k, v] of Object.entries(got.upload.fields)) form.append(k, v);
      form.append("file", new Blob([file.bytes as Uint8Array<ArrayBuffer>], { type: file.mimetype }), file.name);
      const res = await fetch(got.upload.url, { method: "POST", body: form, signal: AbortSignal.timeout(60_000) });
      if (!res.ok) throw new AppsError(`Close didn't take the file (${res.status})`);
      return { url: got.download.url, filename: file.name, content_type: file.mimetype, size: file.bytes.length };
    },
  },
  download_file: {
    description: "Download a file from Close to the computer: a lead's file (list_files_attached_to_lead gives its download_url), or an email, note or SMS attachment's url.",
    readOnly: true,
    input: z.object({ url: z.string().describe("The file's link in Close, like https://app.close.com/go/file/...") }),
    run: async (i: { url: string }, key: string) => {
      if (!CLOSE_HOST.test(i.url)) throw new AppsError("url: only Close's own file links (close.com) can be downloaded with the Close key");
      let res = await fetch(i.url, { headers: { Authorization: basic(key) }, redirect: "manual", signal: AbortSignal.timeout(60_000) });
      // Close hands the file over from storage elsewhere; the key isn't sent there
      const to = res.status >= 300 && res.status < 400 ? res.headers.get("location") : null;
      if (to) res = await fetch(new URL(to, i.url), { signal: AbortSignal.timeout(60_000) });
      if (!res.ok) throw new AppsError(`Close: couldn't download the file (${res.status})`);
      const disposition = /filename\*?=(?:UTF-8'')?"?([^";]+)"?/i.exec(res.headers.get("content-disposition") ?? "")?.[1];
      const name = decodeURIComponent(disposition ?? new URL(i.url).pathname.split("/").filter(Boolean).pop() ?? "download");
      return new AppFile(name, res.headers.get("content-type")?.split(";")[0] || "application/octet-stream", new Uint8Array(await res.arrayBuffer()));
    },
  },
};

const ME: Send = { method: "GET", path: "/me/", query: [], headers: [] };

export const close: OwnApp = {
  app: "close",
  name: "Close",
  logo: "/logos/close.svg",
  keyField: {
    label: "API key",
    help: "In Close, open Settings → Developer → API Keys and click + New API Key. Give it a name like Emplio and copy the key (it's shown once). Emplio can then see and change whatever your Close user can. Setting up automations from Close events works for any user; an admin's key also sees the whole organization's events.",
    placeholder: "api_xxxxxxxxxxxxxxxxxxxxxx.xxxxxxxxxxxxxxxxxxxxxx",
  },
  async check(key) {
    const me = (await call(api, key, ME, {})) as { first_name?: string; last_name?: string; email?: string; organizations?: { name?: string }[] };
    const who = [me.first_name, me.last_name].filter(Boolean).join(" ") || me.email || "Close";
    const org = me.organizations?.[0]?.name;
    return org ? `${who} (${org})` : who;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(api, delivery, key),
    wanted,
  },
  actions: { ...generated, ...extras },
};
